import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    a.sort()

    if k == 1:
        print(a[0])
    else:
        print(a[n - k])

if __name__ == "__main__":
    solve()
"}

