def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

n = int(input())
a = list(map(int, input().split()))

# Count the number of 1s and 2s
count_1 = a.count(1)
count_2 = a.count(2)

# Start with 2 if possible to get a prime immediately
if count_2 > 0:
    result = [2]
    count_2 -= 1

    # Alternate between 1 and 2
    while count_1 > 0 and count_2 > 0:
        result.append(1)
        count_1 -= 1
        result.append(2)
        count_2 -= 1

    # Add remaining 1s
    while count_1 > 0:
        result.append(1)
        count_1 -= 1
else:
    # All are 1s, start with 1
    result = [1]
    while count_1 > 1:
        result.append(1)
        count_1 -= 1

print(' '.join(map(str, result)))
