def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_range(a, b):
    # Compute GCD of all elements from index a to b (0-indexed)
    # Using segment tree
    pass

# Build segment tree
# Each node stores (gcd_value, count_of_gcd)

def build_tree(arr, tree, node, start, end):
    if start == end:
        tree[node] = (arr[start], 1)
    else:
        mid = (start + end) // 2
        build_tree(arr, tree, 2*node, start, mid)
        build_tree(arr, tree, 2*node+1, mid+1, end)
        left_gcd, left_count = tree[2*node]
        right_gcd, right_count = tree[2*node+1]
        if left_gcd == right_gcd:
            tree[node] = (left_gcd, left_count + right_count)
        else:
            tree[node] = (gcd(left_gcd, right_gcd), left_count + right_count)

# Query segment tree
# Returns (gcd_value, count_of_gcd) for range [l, r]

def query_tree(tree, node, start, end, l, r):
    if r < start or end < l:
        return (0, 0)
    if l <= start and end <= r:
        return tree[node]
    mid = (start + end) // 2
    left_gcd, left_count = query_tree(tree, 2*node, start, mid, l, r)
    right_gcd, right_count = query_tree(tree, 2*node+1, mid+1, end, l, r)
    if left_gcd == 0 or right_gcd == 0:
        return (left_gcd + right_gcd, left_count + right_count)
    if left_gcd == right_gcd:
        return (left_gcd, left_count + right_count)
    else:
        return (gcd(left_gcd, right_gcd), left_count + right_count)

# Main
n = int(input())
s = list(map(int, input().split()))
t = int(input())
queries = []
for _ in range(t):
    l, r = map(int, input().split())
    queries.append((l-1, r-1))  # Convert to 0-indexed

# Build segment tree
size = 1
while size < n:
    size <<= 1

# Tree size: 2*size
# We'll use a dictionary for dynamic allocation
# Or we can use a list with size 2*size
# Let's use a list with size 2*size
# But we need to handle up to 2*size
# Let's use a dictionary for simplicity

# Build tree using dictionary
from collections import defaultdict

# Tree dictionary: key = node index, value = (gcd, count)
tree = defaultdict(lambda: (0, 0))
build_tree(s, tree, 1, 0, n-1)

# Process queries
for l, r in queries:
    gcd_val, count = query_tree(tree, 1, 0, n-1, l, r)
    ants_eaten = (r - l + 1) - count
    print(ants_eaten)
