n, h, l, r = map(int, input().split())
a = list(map(int, input().split()))

# dp[i][t] = max good sleeps after i sleeps with current time t
dp = [[-1 for _ in range(h)] for _ in range(n + 1)]
dp[0][0] = 0  # 0 sleeps, time 0, 0 good sleeps

for i in range(1, n + 1):
    for t in range(h):
        if dp[i-1][t] == -1:
            continue

        # Sleep after a_i hours
        new_time = (t + a[i-1]) % h
        if l <= new_time <= r:
            dp[i][new_time] = max(dp[i][new_time], dp[i-1][t] + 1)
