def mex(s):
    i = 0
    while i in s:
        i += 1
    return i

def grundy(L, k, memo):
    if L in memo:
        return memo[L]

    s = set()

    # Find all divisors t > 1 such that L/t >= k
    for t in range(2, L + 1):
        if L % t == 0:
            part_length = L // t
            if part_length >= k:
                # Compute Grundy number for this move
                if t % 2 == 0:
                    # Even number of identical parts, XOR = 0
                    g = 0
                else:
                    # Odd number of identical parts, XOR = g(part_length)
                    g = grundy(part_length, k, memo)
                s.add(g)

    result = mex(s)
    memo[L] = result
    return result

n, m, k = map(int, input().split())

# Compute Grundy number for a single log
memo = {}
g = grundy(m, k, memo)

# If Grundy number is non-zero, Timur wins
if g != 0:
    print("Timur")
else:
    print("Marsel")
"}

