import math

def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def solve():
    N = int(input())
    cities = []
    for _ in range(N):
        x, y, f = map(int, input().split())
        cities.append((x, y, f))

    dp = [0.0] * N
    dp[0] = cities[0][2]

    for i in range(1, N):
        max_happiness = -float('inf')
        for j in range(i):
            dist = distance(cities[j], cities[i])
            happiness = dp[j] + cities[i][2] - dist
            if happiness > max_happiness:
                max_happiness = happiness
        dp[i] = max_happiness

    print(f"{dp[N-1]:.6f}")

solve()
"}

