for char in s:
    if char in {',', ';'}:
        if current_word:
            words.append(current_word)
            current_word = ""
        # Add empty word for the separator
        words.append("")
        current_word = ""
    else:
        current_word += char

# Add the last word
if current_word:
    words.append(current_word)

# Build strings a and b
a_words = []
b_words = []

for word in words:
    if word == "":
        b_words.append(word)
    else:
        # Check if it's a valid nonnegative integer
        if all(c.isdigit() for c in word):
            if len(word) == 1 or (len(word) > 1 and word[0] != '0'):
                a_words.append(word)
            else:
                b_words.append(word)
        else:
            b_words.append(word)

# Build output strings
a_str = ",".join(a_words) if a_words else "-"
b_str = ",".join(b_words) if b_words else "-"

print(f'"{a_str}"')
print(f'"{b_str}"')
"}

