for _ in range(t):
    n = int(input())
    a = list(map(int, input().split()))

    # Count even and odd elements
    even = sum(1 for x in a if x % 2 == 0)
    odd = n - even

    # Check if it's possible
    if n % 2 == 1:
        if abs(even - odd) > 1:
            print(-1)
            continue
    else:
        if even != odd:
            print(-1)
            continue

    # Calculate minimal swaps for both patterns
    # Pattern 1: even, odd, even, odd, ...
    # Pattern 2: odd, even, odd, even, ...

    # For pattern 1: even at even indices (0-based), odd at odd indices
    swaps1 = 0
    for i in range(n):
        if i % 2 == 0 and a[i] % 2 == 1:
            swaps1 += 1
        elif i % 2 == 1 and a[i] % 2 == 0:
            swaps1 += 1

    # For pattern 2: odd at even indices, even at odd indices
    swaps2 = 0
    for i in range(n):
        if i % 2 == 0 and a[i] % 2 == 0:
            swaps2 += 1
        elif i % 2 == 1 and a[i] % 2 == 1:
            swaps2 += 1

    print(min(swaps1, swaps2))
