{"code": "
import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    V = int(data[idx]); idx += 1
    E = int(data[idx]); idx += 1
    K = int(data[idx]); idx += 1

    # Build adjacency list
    adj = [[] for _ in range(V)]
    for _ in range(E):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        c = int(data[idx]); idx += 1
        adj[u].append((v, c))

    # best_score[v][e] = max score to reach node v with exactly e edges
    # We'll use a dictionary of dictionaries for efficiency
    best_score = {v: {} for v in range(V)}

    # Initialize: start at each node with 0 edges and score 0
    for v in range(V):
        best_score[v][0] = 0

    # Use BFS by number of edges
    queue = deque()
    for v in range(V):
        queue.append((v, 0))

    while queue:
        v, e = queue.popleft()

        # Try all outgoing edges
        for next_v, c in adj[v]:
            new_e = e + 1
            new_score = best_score[v][e] + c

            # If we can reach next_v with fewer edges, update
            if new_e not in best_score[next_v] or new_score > best_score[next_v][new_e]:
                best_score[next_v][new_e] = new_score
                queue.append((next_v, new_e))

    # Find the minimum number of edges to reach score >= K
    min_edges = None
    for v in range(V):
        for e in sorted(best_score[v].keys()):
            if best_score[v][e] >= K:
                if min_edges is None or e < min_edges:
                    min_edges = e
                break  # Since we're sorted by edges, first one is minimum

    if min_edges is None:
        print(-1)
        return

    # Find any path with min_edges edges that achieves score >= K
    # We'll use BFS again to reconstruct the path

    # best_path[v][e] = (prev_node, edge_count)
    best_path = {v: {} for v in range(V)}

    # Reconstruct paths
    for v in range(V):
        for e in sorted(best_score[v].keys()):
            if best_score[v][e] >= K:
                # Find the path
                path = []
                current_v = v
                current_e = e

                while current_e > 0:
                    # Find which edge led to current_v with current_e edges
                    for prev_v, c in adj[current_v]:
                        if current_e - 1 in best_score[prev_v] and best_score[prev_v][current_e - 1] + c == best_score[current_v][current_e]:
                            path.append(current_v)
                            current_v = prev_v
                            current_e -= 1
                            break

                path.append(current_v)
                path.reverse()

                # Output
                print(min_edges)
                if min_edges <= 100:
                    print(' '.join(map(str, path)))
                return

    print(-1)

if __name__ == '__main__':
    solve()
