def count_lucky_numbers_less_or_equal(n: str) -> int:
    """Count lucky numbers with the same number of digits as n that are less than or equal to n."""
    count = 0

    # Use a recursive approach to count valid numbers
    def dfs(pos: int, tight: bool, leading_zero: bool) -> int:
        if pos == len(n):
            return 1 if not leading_zero else 0

        limit = int(n[pos]) if tight else 9
        total = 0

        for digit in range(0, limit + 1):
            if digit == 0 and leading_zero:
                # Skip leading zeros
                continue

            if digit not in {4, 7}:
                continue

            new_tight = tight and (digit == limit)
            new_leading_zero = leading_zero and (digit == 0)
            total += dfs(pos + 1, new_tight, new_leading_zero)

        return total

    return dfs(0, True, True)

def solve():
    n = input().strip()

    # Count lucky numbers with fewer digits
    length = len(n)
    count = 0
    for i in range(1, length):
        count += 2 ** i

    # Count lucky numbers with the same number of digits that are less than or equal to n
    count += count_lucky_numbers_less_or_equal(n)

    print(count)

solve()
