def max_overlap(a, b):
    """Calculate maximum overlap where a ends and b starts"""
    max_len = 0
    for i in range(1, min(len(a), len(b)) + 1):
        if a[-i:] == b[:i]:
            max_len = i
    return max_len

def solve():
    while True:
        n = int(input())
        if n == 0:
            break
        strings = [input().strip() for _ in range(n)]

        # Calculate overlaps
        overlap = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    overlap[i][j] = max_overlap(strings[i], strings[j])

        # DP with bitmask
        INF = float('inf')
        dp = [[INF] * n for _ in range(1 << n)]

        # Initialize
        for i in range(n):
            dp[1 << i][i] = len(strings[i])

        # DP transition
        for mask in range(1 << n):
            for i in range(n):
                if not (mask & (1 << i)):
                    continue
                if dp[mask][i] == INF:
                    continue

                for j in range(n):
                    if mask & (1 << j):
                        continue

                    new_mask = mask | (1 << j)
                    new_len = dp[mask][i] + len(strings[j]) - overlap[i][j]
                    if new_len < dp[new_mask][j]:
                        dp[new_mask][j] = new_len

        # Find minimum length
        min_len = min(dp[(1 << n) - 1][i] for i in range(n))
        print(min_len)

solve()
"}

