import sys
from collections import deque, defaultdict


def bfs(n, adj, start):
    """Find shortest distances from start using BFS"""
    dist = [float('inf')] * (n + 1)
    dist[start] = 0

    queue = deque([start])

    while queue:
        u = queue.popleft()
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                queue.append(v)

    return dist


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    adj = defaultdict(list)
    edges = []

    for _ in range(m):
        x = int(next(it))
        y = int(next(it))
        z = int(next(it))
        adj[x].append((y, z))
        adj[y].append((x, z))
        edges.append((x, y, z))

    # Find shortest distances from 1 and from n
    dist1 = bfs(n, adj, 1)
    distn = bfs(n, adj, n)

    # Find shortest distance from 1 to n
    shortest_distance = dist1[n]

    # Find all nodes that are on any shortest path
    nodes_on_shortest_path = set()

    for u in range(1, n + 1):
        if dist1[u] + distn[u] == shortest_distance:
            nodes_on_shortest_path.add(u)

    # Find all edges that are on any shortest path
    edges_on_shortest_path = set()

    for x, y, z in edges:
        u = min(x, y)
        v = max(x, y)
        if dist1[u] + distn[v] == shortest_distance or dist1[v] + distn[u] == shortest_distance:
            edges_on_shortest_path.add((u, v))

    # Now find a shortest path that minimizes affected roads
    # We'll use BFS to find a shortest path from 1 to n
    # and then calculate affected roads

    # Find a shortest path from 1 to n
    path = []
    queue = deque([(1, [1])])

    while queue:
        u, path_so_far = queue.popleft()
        if u == n:
            path = path_so_far
            break

        for v, w in adj[u]:
            if dist1[v] == dist1[u] + w:
                queue.append((v, path_so_far + [v]))

    # Calculate affected roads
    affected = 0
    path_set = set()

    for i in range(len(path) - 1):
        u = path[i]
        v = path[i + 1]
        path_set.add((min(u, v), max(u, v)))

    for x, y, z in edges:
        if (min(x, y), max(x, y)) in path_set:
            # Road is on the path
            if z == 0:
                affected += 1  # Needs repair
        else:
            # Road is not on the path
            if z == 1:
                affected += 1  # Needs blowing up

    # Output the result
    print(affected)

    # Output each affected road
    for x, y, z in edges:
        if (min(x, y), max(x, y)) in path_set:
            # Road is on the path
            if z == 0:
                print(x, y, 1)
        else:
            # Road is not on the path
            if z == 1:
                print(x, y, 0)

if __name__ == "__main__":
    solve()
"}

