def solve():
    N = int(input())
    A = list(map(int, input().split()))

    # Count how many numbers have each bit set
    count = [0] * 60  # since A_i < 2^60
    for a in A:
        for k in range(60):
            if a & (1 << k):
                count[k] += 1

    result = 0
    for k in range(60):
        c = count[k]
        contribution = c * (N - c) * (1 << k)
        result = (result + contribution) % MOD

    print(result)

