def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    out_lines = []

    for _ in range(t):
        a = int(data[idx]); idx += 1
        b = int(data[idx]); idx += 1
        c = int(data[idx]); idx += 1
        m = int(data[idx]); idx += 1

        max_pairs = a + b + c - 3
        count_ones = 0
        if a == 1:
            count_ones += 1
        if b == 1:
            count_ones += 1
        if c == 1:
            count_ones += 1

        min_pairs = max(0, max_pairs - 2 * count_ones)

        if min_pairs <= m <= max_pairs:
            out_lines.append("YES")
        else:
            out_lines.append("NO")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
